    placement = {i: [] for i in range(gpu_num)}
    remaining = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num

    def kvpr(gpu):
        return load[gpu] / remaining[gpu]

    def pressure(model):
        return (model.req_rate / model.slo) / (GPU_MEM_SIZE - model.model_size)

    for model in sorted(models, key=pressure, reverse=True):
        weight = model.req_rate / model.slo
        choices = []
        for gpu in range(gpu_num):
